-- BASELINE PROD (SOMENTE LEITURA) — hashes/contagens congelados ANTES da 1ª migration e comparados depois de CADA migration/deploy.
-- "fechado" = dados que não mudam mais (semanas < 2026-10-26): qualquer diferença é regressão. "vivo" = semana corrente (muda com o uso): comparar contagens/marcadores de tempo e explicar diferenças.
-- Não menciona nenhuma tabela/coluna do modelo de rotas (existem só depois da M0); a lista de tabelas antigas EXCLUI as tabelas novas pelo nome.
select 'marcador_t0' k, now()::text a, coalesce((select max(criado_em)::text from apontamentos_producao), '-') b, coalesce((select max(updated_at)::text from previsoes), '-') c
union all select 'cadastros_produtos', count(*)::text, md5(coalesce(string_agg(to_jsonb(p)::text, '|' order by p.id),'')), '' from produtos p
union all select 'cadastros_roteiro_etapas', count(*)::text, md5(coalesce(string_agg(to_jsonb(e)::text, '|' order by e.id),'')), '' from roteiro_etapas e
union all select 'cadastros_roteiro_etapa_maquinas', count(*)::text, md5(coalesce(string_agg(to_jsonb(m)::text, '|' order by m.etapa_id, m.maquina_id),'')), '' from roteiro_etapa_maquinas m
union all select 'cadastros_maquinas', count(*)::text, md5(coalesce(string_agg(to_jsonb(m)::text, '|' order by m.id),'')), '' from maquinas m
union all select 'cadastros_operacoes', count(*)::text, md5(coalesce(string_agg(to_jsonb(o)::text, '|' order by o.id),'')), '' from operacoes o
union all select 'cadastros_periodos', count(*)::text, md5(coalesce(string_agg(to_jsonb(p)::text, '|' order by p.id),'')), '' from periodos p
union all select 'previsoes_todas', count(*)::text, md5(coalesce(string_agg(p.id::text || p.semana_inicio::text, '|' order by p.id),'')), (select max(semana_inicio)::text from previsoes) from previsoes p
union all select 'previsao_itens_fechado', count(*)::text, md5(coalesce(string_agg(to_jsonb(i)::text, '|' order by i.id),'')), '' from previsao_itens i join previsoes p on p.id=i.previsao_id where p.semana_inicio < '2026-10-26'
union all select 'previsao_itens_26_10_vivo', count(*)::text, md5(coalesce(string_agg(to_jsonb(i)::text, '|' order by i.id),'')), '' from previsao_itens i join previsoes p on p.id=i.previsao_id where p.semana_inicio = '2026-10-26'
union all select 'previsao_item_maquinas_fechado', count(*)::text, md5(coalesce(string_agg(to_jsonb(m)::text, '|' order by m.item_id, m.etapa_id, m.maquina_id),'')), '' from previsao_item_maquinas m join previsao_itens i on i.id=m.item_id join previsoes p on p.id=i.previsao_id where p.semana_inicio < '2026-10-26'
union all select 'previsao_item_maquinas_26_10_vivo', count(*)::text, md5(coalesce(string_agg(to_jsonb(m)::text, '|' order by m.item_id, m.etapa_id, m.maquina_id),'')), '' from previsao_item_maquinas m join previsao_itens i on i.id=m.item_id join previsoes p on p.id=i.previsao_id where p.semana_inicio = '2026-10-26'
union all select 'previsao_item_adicional_etapa', count(*)::text, md5(coalesce(string_agg(to_jsonb(a)::text, '|' order by a.item_id, a.etapa_id),'')), '' from previsao_item_adicional_etapa a
union all select 'previsao_dias_equipe_26_10_vivo', (select count(*) from previsao_dias_produtivos d join previsoes p on p.id=d.previsao_id where p.semana_inicio='2026-10-26')::text || '/' || (select count(*) from previsao_equipe_semana e join previsoes p on p.id=e.previsao_id where p.semana_inicio='2026-10-26')::text,
   md5(coalesce((select string_agg(to_jsonb(d)::text, '|' order by d.dia) from previsao_dias_produtivos d join previsoes p on p.id=d.previsao_id where p.semana_inicio='2026-10-26'),'') || coalesce((select string_agg(to_jsonb(e)::text, '|' order by e.funcionario_id) from previsao_equipe_semana e join previsoes p on p.id=e.previsao_id where p.semana_inicio='2026-10-26'),'')), ''
union all select 'previsao_maquinas_indisponiveis', count(*)::text, md5(coalesce(string_agg(to_jsonb(x)::text, '|' order by x.previsao_id, x.maquina_id),'')), '' from previsao_maquinas_indisponiveis x
union all select 'escala_dias_fechado', count(*)::text, md5(coalesce(string_agg(to_jsonb(d)::text, '|' order by d.previsao_id, d.data),'')), '' from escala_producao_dias d where d.data < '2026-10-26'
union all select 'escala_alocacoes_fechado', count(*)::text, md5(coalesce(string_agg(a.data::text||a.periodo_id||a.funcionario_id::text||coalesce(a.maquina_id::text,'')||coalesce(a.produto_id::text,'')||coalesce(a.etapa_id::text,'')||a.pecas::text, '|' order by a.data,a.periodo_id,a.funcionario_id),'')), '' from escala_producao_alocacoes a where a.data < '2026-10-26'
union all select 'escala_alocacoes_26_10_vivo', count(*)::text, md5(coalesce(string_agg(a.data::text||a.periodo_id||a.funcionario_id::text||coalesce(a.maquina_id::text,'')||coalesce(a.produto_id::text,'')||coalesce(a.etapa_id::text,'')||a.pecas::text||coalesce(a.pecas_adicional,0)::text||a.origem||a.excecao_revezamento::text, '|' order by a.data,a.periodo_id,a.funcionario_id),'')), '' from escala_producao_alocacoes a where a.data between '2026-10-26' and '2026-11-01'
union all select 'escala_plano_versoes', count(*)::text, coalesce(max(criado_em)::text, '-'), '' from escala_plano_versoes
union all select 'escala_plano_entrada_26_10_vivo', '1', md5((select public.escala_plano_entrada(id)::text from previsoes where semana_inicio='2026-10-26')), ''
union all select 'escala_parametros', count(*)::text, md5(coalesce(string_agg(chave||valor::text, '|' order by chave),'')), '' from escala_parametros
union all select 'escala_replanejamentos', count(*)::text, md5(coalesce(string_agg(to_jsonb(r)::text, '|' order by r.id),'')), '' from escala_replanejamentos r
union all select 'escala_recurso_indisponivel', count(*)::text, md5(coalesce(string_agg(to_jsonb(r)::text, '|' order by r.id),'')), '' from escala_recurso_indisponivel r
union all select 'apontamentos_fechado', count(*)::text, md5(coalesce(string_agg(to_jsonb(a)::text, '|' order by a.id),'')), '' from apontamentos_producao a where a.data < '2026-10-26'
union all select 'apontamentos_26_10_vivo', count(*)::text, md5(coalesce(string_agg(to_jsonb(a)::text, '|' order by a.id),'')), '' from apontamentos_producao a where a.data between '2026-10-26' and '2026-11-01'
union all select 'wip_tabelas', (select count(*) from wip_controle)::text || '/' || (select count(*) from wip_ajustes)::text || '/' || (select count(*) from wip_confirmacoes)::text || '/' || (select count(*) from wip_saldo_semanal)::text, '', ''
union all select 'funcionarios_custos', (select count(*) from funcionarios)::text || '/' || (select count(*) from funcionario_custos)::text || '/' || (select count(*) from fixed_costs)::text, md5((select string_agg(to_jsonb(f)::text, '|' order by f.id) from funcionarios f) || (select coalesce(string_agg(to_jsonb(c)::text, '|' order by c.id),'') from fixed_costs c)), ''
union all select 'valor_atribuido_lineares', count(*)::text, md5(coalesce(string_agg(r::text, '|' order by r.produto_id, r.operacao_id, r.periodo_id), '')), ''
  from (select p.id produto_id, e.operacao_id, per.id periodo_id, public.calcular_valor_atribuido_operacao(p.id, e.operacao_id, per.id) val from produtos p join roteiro_etapas e on e.produto_id = p.id cross join periodos per) r
union all select 'tabelas_antigas_colunas', count(*)::text, md5(string_agg(c.relname||'.'||a.attname||':'||format_type(a.atttypid,a.atttypmod), '|' order by c.relname, a.attnum)), ''
  from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
 where c.relnamespace='public'::regnamespace and c.relkind='r' and c.relname not in ('produto_rota','rota_etapas','produto_pool_comum','previsao_rota_limite','escala_rota_divisao','produto_variante_legada','rotas_config','rotas_planejador_sombra') and not (c.relname='previsoes' and a.attname='modelo_rotas')
union all select 'funcoes_publicas', count(*)::text, md5(string_agg(p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')', '|' order by p.proname, pg_get_function_identity_arguments(p.oid))), ''
  from pg_proc p where p.pronamespace='public'::regnamespace and p.proname not in ('produto_rotas_validar','produto_rotas_trg_validar','rota_etapas_trg_mesmo_produto','produto_variante_legada_trg','previsao_itens_trg_modelo_rotas','previsoes_trg_modelo_rotas','rotas_suporte_ativo','produto_de_rotas_guard','produto_estrutura_rotas','produto_etapa_final','produto_usa_rotas','etapa_grupo_rota','produto_arestas_rotas','apontamentos_trg_etapa_do_produto_rotas','produto_rotas_maquinas_ambiguas','previsao_itens_trg_adicional_rotas','previsao_item_adicional_etapa_trg_rotas','etapas_do_percurso','escala_rota_divisao_semana')
union all select 'funcoes_corpo_alteradas_pelo_m4', '3', md5(pg_get_functiondef('public.obter_indicadores_producao(date,date,uuid,uuid,uuid,uuid,text)'::regprocedure) || pg_get_functiondef('public.obter_apontado_real_previsao_por_semana(date)'::regprocedure) || pg_get_functiondef('public.wip_controle_criar(uuid,uuid,uuid,uuid,date,numeric)'::regprocedure) || pg_get_functiondef('public.calcular_valor_atribuido_operacao(uuid,uuid,text)'::regprocedure)), 'corpo anterior; muda de propósito na migration 20261109100000/110000';
